<?php
declare(strict_types=1);
require_once __DIR__.'/includes/functions.php';
require_once __DIR__.'/classes/RecipeRepository.php';
$repo=new RecipeRepository();
$id=(int)($_GET['id']??0);
$recipe=$repo->find($id, true);
$canPreviewUnapproved=$recipe && $recipe['status']!=='approved' && (is_admin() || (is_logged_in() && (int)$recipe['author_id']===(int)current_user()['id']));
if(!$recipe || ($recipe['status']!=='approved' && !$canPreviewUnapproved)){http_response_code(404);$pageTitle='Recipe not found';require __DIR__.'/includes/header.php';echo '<section class="section container"><div class="empty-state"><h1>Recipe not found</h1><p>This recipe may be awaiting moderation or may have been removed.</p></div></section>';require __DIR__.'/includes/footer.php';exit;}
$repo->incrementViews($id);
$ingredients=$repo->ingredients($id);$steps=$repo->steps($id);$media=$repo->media($id);$tags=$repo->tags($id);$nutrition=$repo->nutrition($id);$comments=$repo->comments($id);
$isFav=false;$myRating=0;$folders=[];
if(is_logged_in()){
 $stmt=db()->prepare('SELECT 1 FROM favorites WHERE user_id=? AND recipe_id=?');$stmt->execute([current_user()['id'],$id]);$isFav=(bool)$stmt->fetchColumn();
 $stmt=db()->prepare('SELECT rating FROM ratings WHERE user_id=? AND recipe_id=?');$stmt->execute([current_user()['id'],$id]);$myRating=(int)($stmt->fetchColumn()?:0);
 $stmt=db()->prepare('SELECT id,name FROM bookmark_folders WHERE user_id=? ORDER BY name');$stmt->execute([current_user()['id']]);$folders=$stmt->fetchAll();
}
$servings=max(1,(int)$recipe['servings']);
$shareUrl='http'.(!empty($_SERVER['HTTPS'])?'s':'').'://'.($_SERVER['HTTP_HOST']??'localhost').url('recipe.php?id='.$id);
$shareText='Try this CookBook recipe: '.$recipe['title'];
$pageTitle=$recipe['title'];require __DIR__.'/includes/header.php';
?>
<section class="recipe-detail-head"><div class="container recipe-detail-grid"><div><div class="tag-row"><?php if($recipe['is_sponsored']):?><span class="pill sponsored">Sponsored</span><?php endif;?><?php if($recipe['is_premium']):?><span class="pill premium">Premium</span><?php endif;?><?php foreach($tags as $tag):?><span class="tag"><?=e($tag)?></span><?php endforeach;?></div><h1><?=e($recipe['title'])?></h1><p class="lead"><?=e($recipe['description'])?></p><div class="author-row"><img src="<?=e(avatar_url($recipe['author_image']))?>" alt=""><div><span>Recipe by</span><a href="<?=e(url('profile.php?id='.(int)$recipe['author_id']))?>"><strong><?=e($recipe['author_name'])?></strong></a></div></div><div class="recipe-facts"><div><strong><?= (int)$recipe['prep_minutes'] ?></strong><span>prep min</span></div><div><strong><?= (int)$recipe['cook_minutes'] ?></strong><span>cook min</span></div><div><strong><?= (int)$recipe['servings'] ?></strong><span>servings</span></div><div><strong><?= number_format((float)$recipe['avg_rating'],1) ?></strong><span>rating</span></div></div><div class="recipe-actions"><?php if(is_logged_in()):?><form method="post" action="<?=e(url('favorite_action.php'))?>"><?=csrf_field()?><input type="hidden" name="recipe_id" value="<?=$id?>"><button class="button <?=$isFav?'button-secondary':'button-primary'?>"><?=$isFav?'♥ Saved':'♡ Save recipe'?></button></form><?php else:?><a class="button button-primary" href="<?=e(url('login.php'))?>">♡ Sign in to save</a><?php endif;?><?php if(is_logged_in()):?><a class="button button-ghost" href="<?=e(url('bookmarks.php?recipe_id='.$id))?>">Save to collection</a><?php endif;?><button class="button button-ghost copy-link" data-copy="<?=e($shareUrl)?>">Copy link</button><a class="button button-ghost" href="mailto:?subject=<?=rawurlencode($recipe['title'])?>&body=<?=rawurlencode($shareText.' '.$shareUrl)?>">Email</a><a class="button button-ghost" target="_blank" rel="noopener" href="https://www.facebook.com/sharer/sharer.php?u=<?=rawurlencode($shareUrl)?>">Facebook</a><a class="button button-ghost" target="_blank" rel="noopener" href="https://twitter.com/intent/tweet?text=<?=rawurlencode($shareText)?>&url=<?=rawurlencode($shareUrl)?>">X</a><a class="button button-ghost" target="_blank" rel="noopener" href="https://wa.me/?text=<?=rawurlencode($shareText.' '.$shareUrl)?>">WhatsApp</a></div></div><div class="recipe-cover"><img src="<?=e(recipe_image($recipe['cover_image']))?>" alt="<?=e($recipe['title'])?>"></div></div></section>
<section class="section container recipe-content-grid"><article class="recipe-main"><section class="panel"><div class="section-heading compact"><div><span class="eyebrow">Ingredients</span><h2>What you’ll need</h2></div><button class="button button-ghost button-small" type="button" data-serving-toggle data-base-servings="<?=$servings?>">Adjust servings</button></div><div class="ingredient-list" data-serving-list data-base-servings="<?=$servings?>"><?php foreach($ingredients as $i):?><div class="ingredient-row"><?php if($i['image_path']):?><img src="<?=e(recipe_image($i['image_path']))?>" alt=""><?php endif;?><span class="ingredient-qty" data-qty="<?=e((string)$i['quantity'])?>"><?=e((string)$i['quantity'])?></span><span><?=e($i['unit'])?></span><strong><?=e($i['name'])?></strong><?php if($i['notes']):?><small><?=e($i['notes'])?></small><?php endif;?></div><?php endforeach;?></div></section><section class="panel"><span class="eyebrow">Method</span><h2>Step-by-step</h2><div class="steps-list"><?php foreach($steps as $step):?><article class="step-card"><span class="step-number"><?=$step['step_number']?></span><div><p><?=nl2br(e($step['instruction']))?></p><?php if($step['image_path']):?><img src="<?=e(recipe_image($step['image_path']))?>" alt="Step <?=$step['step_number']?> image"><?php endif;?></div></article><?php endforeach;?></div></section><?php if($media):?><section class="panel"><span class="eyebrow">Gallery</span><h2>Recipe media</h2><div class="media-gallery"><?php foreach($media as $m):?><?php if($m['media_type']==='image'):?><img src="<?=e(url($m['file_path']))?>" alt="Recipe gallery image"><?php elseif($m['media_type']==='video'):?><video controls preload="metadata"><source src="<?=e(url($m['file_path']))?>"></video><?php else:?><a href="<?=e($m['external_url'])?>" target="_blank" rel="noopener">Watch attached video ↗</a><?php endif;?><?php endforeach;?></div></section><?php endif;?></article>
<aside class="recipe-side"><?php if($nutrition):?><section class="panel sticky-panel"><span class="eyebrow">Nutrition</span><h2>Per serving</h2><p class="muted">Calculated from totals entered by the recipe creator.</p><div class="nutrition-grid"><div><strong><?=round((float)$nutrition['calories_total']/$servings)?></strong><span>kcal</span></div><div><strong><?=number_format((float)$nutrition['protein_g_total']/$servings,1)?></strong><span>g protein</span></div><div><strong><?=number_format((float)$nutrition['carbs_g_total']/$servings,1)?></strong><span>g carbs</span></div><div><strong><?=number_format((float)$nutrition['fat_g_total']/$servings,1)?></strong><span>g fat</span></div></div><?php if($nutrition['notes']):?><small><?=e($nutrition['notes'])?></small><?php endif;?></section><?php endif;?><section class="panel"><span class="eyebrow">Recipe details</span><dl class="detail-list"><div><dt>Cuisine</dt><dd><?=e($recipe['cuisine'])?></dd></div><div><dt>Category</dt><dd><?=e($recipe['category'])?></dd></div><div><dt>Difficulty</dt><dd><?=e($recipe['difficulty'])?></dd></div><div><dt>Views</dt><dd><?=number_format((int)$recipe['views']+1)?></dd></div><div><dt>Saves</dt><dd><?=number_format((int)$recipe['favorite_count'])?></dd></div></dl></section></aside></section>
<section class="section section-soft"><div class="container"><div class="section-heading"><div><span class="eyebrow">Community</span><h2>Ratings & discussion</h2></div><div class="rating-large"><strong><?=number_format((float)$recipe['avg_rating'],1)?></strong><span><?=e(stars((float)$recipe['avg_rating']))?> · <?=$recipe['rating_count']?> ratings</span></div></div><?php if(is_logged_in()):?><div class="community-form-grid"><form class="panel" method="post" action="<?=e(url('rating_action.php'))?>"><?=csrf_field()?><input type="hidden" name="recipe_id" value="<?=$id?>"><h3>Your rating</h3><div class="rating-input"><?php for($n=1;$n<=5;$n++):?><label><input type="radio" name="rating" value="<?=$n?>" <?=$myRating===$n?'checked':''?>><span>★</span><small><?=$n?></small></label><?php endfor;?></div><button class="button button-secondary">Save rating</button></form><form class="panel" method="post" action="<?=e(url('comment_action.php'))?>"><?=csrf_field()?><input type="hidden" name="recipe_id" value="<?=$id?>"><h3>Join the discussion</h3><label class="sr-only" for="comment">Comment</label><textarea id="comment" name="body" rows="4" maxlength="1000" required placeholder="Share a cooking tip, question or feedback..."></textarea><button class="button button-primary">Post comment</button></form></div><?php else:?><div class="panel"><p><a href="<?=e(url('login.php'))?>">Sign in</a> to rate, comment and save this recipe.</p></div><?php endif;?><div class="comments-list"><?php if(!$comments):?><div class="empty-state"><p>No comments yet. Start the discussion.</p></div><?php endif;?><?php foreach($comments as $c):?><article class="comment"><img src="<?=e(avatar_url($c['profile_image']))?>" alt=""><div><header><strong><?=e($c['display_name'])?></strong><time><?=e(date('j M Y',strtotime($c['created_at'])))?></time></header><p><?=nl2br(e($c['body']))?></p></div></article><?php endforeach;?></div></div></section>
<?php require __DIR__.'/includes/footer.php'; ?>
